// src/pages/Home.js
import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

export default function Home({ currentUser }) {
  const [status, setStatus] = useState("");
  const [allPredictions, setAllPredictions] = useState([]);

  useEffect(() => {
    const API_URL = process.env.REACT_APP_API_URL;

    fetch(`${API_URL}/`)
      .then((res) => res.text())
      .then((data) => setStatus(data))
      .catch(() => setStatus("Backend not reachable"));

    const stored = JSON.parse(localStorage.getItem("predictionHistory") || "[]");
    setAllPredictions(stored);
  }, []);

  /* ---------- Compute Cluster Counts & Avg Confidence ---------- */
  const clusters = [0, 1, 2, 3];

  // Total predictions per cluster
  const clusterCounts =
    allPredictions.length > 0
      ? clusters.map((c) => allPredictions.filter((p) => p.result?.cluster === c).length)
      : [12, 19, 8, 15];

  // Average confidence per cluster
  const clusterConfidence =
    allPredictions.length > 0
      ? clusters.map((c) => {
          const filtered = allPredictions.filter((p) => p.result?.cluster === c && p.result?.confidence != null);
          const avg =
            filtered.length > 0
              ? filtered.reduce((acc, p) => acc + p.result.confidence, 0) / filtered.length
              : 0;
          return +(avg * 100).toFixed(2); // convert to percentage
        })
      : [80, 75, 60, 90]; // fallback demo

  const clusterData = {
    labels: clusters.map((c) => `Cluster ${c}`),
    datasets: [
      {
        label: "Companies",
        data: clusterCounts,
        backgroundColor: "#3b82f6",
      },
    ],
  };

  const confidenceData = {
    labels: clusters.map((c) => `Cluster ${c}`),
    datasets: [
      {
        label: "Avg Confidence (%)",
        data: clusterConfidence,
        backgroundColor: "#10b981",
      },
    ],
  };

  /* ---------- KPIs ---------- */
  const kpis = [
    { title: "Total Predictions", value: allPredictions.length || 54 },
    {
      title: "Avg Cluster",
      value:
        allPredictions.length > 0
          ? (
              allPredictions.reduce((acc, p) => acc + (p.result?.cluster || 0), 0) /
              allPredictions.length
            ).toFixed(2)
          : "1.87",
    },
    {
      title: "Successful Saves",
      value:
        allPredictions.length > 0
          ? allPredictions.filter((p) => p.result && !p.result.error).length
          : 48,
    },
    { title: "Backend Status", value: status || "Connected" },
  ];

  return (
    <div
      style={{
        padding: "40px",
        width: "100%",
        minHeight: "100vh",
        fontFamily: "'Inter', Arial, sans-serif",
        background: "#f8fafc",
      }}
    >
      <h1
        style={{
          textAlign: "center",
          marginBottom: "40px",
          color: "#1e3c72",
          fontSize: "32px",
        }}
      >
        Company Growth Analytics
      </h1>

      {/* Charts */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "25px",
          marginTop: "20px",
        }}
      >
        <div
          style={{
            background: "#fff",
            padding: "25px",
            borderRadius: "14px",
            boxShadow: "0 10px 25px rgba(0,0,0,0.05)",
          }}
        >
          <h3 style={{ textAlign: "center", color: "#1e3c72" }}>Growth Cluster Distribution</h3>
          <Bar data={clusterData} />
        </div>

        <div
          style={{
            background: "#fff",
            padding: "25px",
            borderRadius: "14px",
            boxShadow: "0 10px 25px rgba(0,0,0,0.05)",
          }}
        >
          <h3 style={{ textAlign: "center", color: "#1e3c72" }}>Prediction Confidence per Cluster</h3>
          <Bar data={confidenceData} />
        </div>
      </div>

      {/* KPIs */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
          gap: "20px",
          marginTop: "30px",
        }}
      >
        {kpis.map((kpi, idx) => (
          <div
            key={idx}
            style={{
              background: "white",
              borderRadius: "14px",
              padding: "25px",
              boxShadow: "0 10px 25px rgba(0,0,0,0.05)",
              textAlign: "center",
            }}
          >
            <h4 style={{ marginBottom: "10px" }}>{kpi.title}</h4>
            <p style={{ fontSize: "24px", fontWeight: "600", color: "#2563eb" }}>{kpi.value}</p>
          </div>
        ))}
      </div>

      {/* Go to Predict Page */}
      <div style={{ textAlign: "center", marginTop: "30px" }}>
        <Link
          to="/predict"
          style={{
            padding: "15px 35px",
            backgroundColor: "#2563eb",
            color: "white",
            fontWeight: "bold",
            textDecoration: "none",
            borderRadius: "10px",
            fontSize: "16px",
          }}
        >
          Go to Predict Page
        </Link>
      </div>
    </div>
  );
}
